from decimal import Decimal, ROUND_HALF_UP


def fee(amount: float) -> float:
    """Processing fee: 1% of the amount, rounded to cents."""
    value = Decimal(str(amount)) * Decimal("0.01") * Decimal("100")
    return float(value.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP))

import pytest

from payments.fees import fee


def test_fee_basic():
    assert fee(100.0) == 100.0


@pytest.mark.parametrize(
    ("amount", "expected"),
    [(2.675, 2.68), (1.005, 1.01), (2.674, 2.67), (0.0, 0.0)],
)
def test_fee_rounding_contract(amount, expected):
    assert fee(amount) == expected
